# Databricks notebook source
# Installs Databricks' official dbx_oracle_setup_util, creates a dedicated CDC
# replication user, grants it, grants SELECT on the DEMO schema, and validates.
# Runs as oracleadmin over TLS/2484 on serverless.

# COMMAND ----------
# MAGIC %pip install oracledb --quiet

# COMMAND ----------
dbutils.library.restartPython()

# COMMAND ----------
import oracledb, ssl, json, base64, re

for w in ["host","port","service","admin_user","admin_password","cdc_user","cdc_password","src_schema"]:
    dbutils.widgets.text(w,"")
host=dbutils.widgets.get("host"); port=int(dbutils.widgets.get("port"))
service=dbutils.widgets.get("service")
admin_user=dbutils.widgets.get("admin_user"); admin_password=dbutils.widgets.get("admin_password")
cdc_user=dbutils.widgets.get("cdc_user"); cdc_password=dbutils.widgets.get("cdc_password")
src_schema=dbutils.widgets.get("src_schema")

# The two base64 blobs below are PUBLIC and NOT sensitive (no private keys / secrets):
#  - the Amazon RDS GovCloud CA chain (server-verification cert)
#  - Databricks' official dbx_oracle_setup_util package (dbx-oracle-setup-package.sql)

open("/tmp/rds-ca.pem","wb").write(base64.b64decode(""))
pkg_sql = base64.b64decode("").decode()

ctx=ssl.create_default_context(cafile="/tmp/rds-ca.pem")
ctx.minimum_version=ssl.TLSVersion.TLSv1_2
try: ctx.set_ciphers("DEFAULT:@SECLEVEL=1")
except Exception: pass
dsn=(f"(description=(address=(protocol=tcps)(host={host})(port={port}))"
     f"(connect_data=(service_name={service}))(security=(ssl_server_dn_match=yes)))")
conn=oracledb.connect(user=admin_user,password=admin_password,dsn=dsn,ssl_context=ctx)
cur=conn.cursor()
res={}

# Install the package: split on lines that are just "/"
blocks=[b.strip() for b in re.split(r"(?m)^\s*/\s*$", pkg_sql) if b.strip()]
for i,b in enumerate(blocks):
    try:
        cur.execute(b); res[f"install_block_{i}"]="OK"
    except Exception as e:
        res[f"install_block_{i}"]="FAIL "+str(e).splitlines()[0]
# check compile errors
try:
    cur.execute("select name,type,line,text from user_errors where name='DBX_ORACLE_SETUP_UTIL' order by sequence")
    errs=cur.fetchall(); res["package_errors"]=[tuple(r) for r in errs] if errs else "none"
except Exception as e:
    res["package_errors"]="check FAIL "+str(e).splitlines()[0]

def call(label, plsql):
    try:
        cur.execute(plsql); conn.commit(); res[label]="OK"
    except Exception as e:
        res[label]="FAIL "+str(e).splitlines()[0]

call("create_user", f"begin dbx_oracle_setup_util.create_user('{cdc_user}','{cdc_password}','USERS','TEMP'); end;")
call("grant_permissions", f"begin dbx_oracle_setup_util.grant_permissions('{cdc_user}'); end;")
call("grant_select_permissions", f"begin dbx_oracle_setup_util.grant_select_permissions('{cdc_user}','{src_schema}'); end;")

# validate_setup with dbms_output captured
try:
    cur.callproc("dbms_output.enable",(None,))
    cur.execute(f"begin dbx_oracle_setup_util.validate_setup('{cdc_user}'); end;")
    lines=[]; line=cur.var(str); status=cur.var(int)
    while True:
        cur.callproc("dbms_output.get_line",(line,status))
        if status.getvalue()!=0: break
        lines.append(line.getvalue())
    res["validate_setup"]="OK"; res["validate_output"]=lines
except Exception as e:
    res["validate_setup"]="FAIL "+str(e).splitlines()[0]

cur.close(); conn.close()
for k,v in res.items(): print(k,"=",v)
dbutils.notebook.exit(json.dumps(res, default=str))
